/* \u53EA\u501F\u7528 alpha \u906E\u7F69\u7B97\u6CD5\uFF1BcurrentColor \u4EC5\u63D0\u4F9B\u4E0D\u900F\u660E\u5EA6\uFF0C\u4E0D\u5728\u5185\u5BB9\u4E0A\u7ED8\u5236\u989C\u8272\u3002 */
